input.old_string:
.sort((a, b) => {
  const dateA = a.frontmatter.date || "1970-01-01";
  const dateB = b.frontmatter.date || "1970-01-01";
  return dateB.localeCompare(dateA);
});

input.new_string:
.sort((a, b) => {
  const dateA = String(a.frontmatter.date || "1970-01-01");
  const dateB = String(b.frontmatter.date || "1970-01-01");
  return dateB.localeCompare(dateA);
});

input.command:
REPLICATE_API_TOKEN=$(grep REPLICATE_API_TOKEN ~/.env | cut -d= -f2)

# image-4: Aged larch terrace with silver patina — the WORST image (4/10)
curl -s -X POST "https://api.replicate.com/v1/models/black-forest-labs/flux-2-max/predictions" \
  -H "Authorization: Bearer $REPLICATE_API_TOKEN" \
  -H "Content-Type: application/json" \
  -d '{
    "input": {
      "prompt": "Photorealistic architectural photograph of a 3-year-old premium timber frame terrace showing beautiful natural silver patina on larch decking boards. Massive post-and-beam glulam structure with visible knee brace joints weathered to silver-grey. Morning golden light, dew drops on aged wood surface. Dense wood grain texture clearly visible. Birch trees and mixed forest in soft focus background, summer in Leningrad Oblast Russia. The terrace looks premium and well-maintained despite natural aging. Magazine quality moody atmospheric photography. Dark warm tones, no bright whites.",
      "aspect_ratio": "16:9",
      "num_inference_steps": 50,
      "guidance": 3.5
    }
  }' | tee /tmp/flux-image4-terrasa.json | python3 -c "import sys,json; d=json.load(sys.stdin); print(d.get('id','ERROR'), d.get('status',''))"

